import { useEffect, useState } from 'react';
import { CheckSquare, CheckCircle2, AlertCircle, FileText } from 'lucide-react';
import { purchasingApi } from '../../services/purchasingApi';
import { financeApi } from '../../services/financeApi';
import { PO, mapPurchaseRequestsToPos, calcTotal } from '../purchasing/purchase-orders-page';
import { usePurchasingData } from '../purchasing/usePurchasingData';
import { MR, mapPurchaseRequestToMr } from '../purchasing/material-requests-page';
import { useApp } from '../context/AppContext';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '../ui/tabs';

// Sub-components
import { PrBudgetTab } from './components/PurchasingApproval/PrBudgetTab';
import { ApPaymentTab } from './components/PurchasingApproval/ApPaymentTab';
import { ApHistoryTab } from './components/PurchasingApproval/ApHistoryTab';
import { PrReviewModal } from './components/PurchasingApproval/PrReviewModal';
import { ApPaymentModal } from './components/PurchasingApproval/ApPaymentModal';

export type POCategory = 'Asset' | 'Consumable' | 'Tools' | 'Project' | 'Maintenance' | '';

export function FinancePurchasingApproval() {
  const { purchaseRequests, suppliers, supplierPayments, refresh } = usePurchasingData();
  const { currentUser } = useApp();
  const [pos, setPos] = useState<PO[]>([]);
  const [mrs, setMrs] = useState<MR[]>([]);
  const [search, setSearch] = useState('');
  
  // Payment states
  const [selectedPo, setSelectedPo] = useState<PO | null>(null);
  const [category, setCategory] = useState<POCategory>('');
  const [notes, setNotes] = useState('');
  const [proofFile, setProofFile] = useState<File | null>(null);

  // Pagination for history
  const [historyPage, setHistoryPage] = useState(1);
  const ITEMS_PER_PAGE = 10;

  // PR Review states
  const [selectedMr, setSelectedMr] = useState<MR | null>(null);
  const [isApproving, setIsApproving] = useState(false);
  const [showRejectModal, setShowRejectModal] = useState(false);
  const [rejectReasonInput, setRejectReasonInput] = useState("");
  const [dialogMsg, setDialogMsg] = useState<{ title: string; message: string } | null>(null);

  useEffect(() => {
    if (!purchaseRequests || purchaseRequests.length === 0) return;
    
    try {
      const allPos = mapPurchaseRequestsToPos(purchaseRequests, supplierPayments, suppliers);
      const paymentPos = allPos.filter(po => po.items.length > 0 && calcTotal(po.items) > 0);
      paymentPos.sort((a, b) => {
        if (a.paymentStatus === "Unpaid" && b.paymentStatus !== "Unpaid") return -1;
        if (a.paymentStatus !== "Unpaid" && b.paymentStatus === "Unpaid") return 1;
        return 0;
      });
      setPos(paymentPos);

      const allMrs = purchaseRequests.map(mapPurchaseRequestToMr);
      const pendingMrs = allMrs.filter(mr => {
        if (mr.backendStatus === "Completed" || mr.status === "Completed") return false;
        
        // Hanya tampilkan di Finance jika Purchasing sudah submit harga (isReadyForFinance)
        // ATAU statusnya memang sedang/sudah diproses oleh Finance
        return mr.isReadyForFinance === true || 
               mr.backendStatus === "FinanceApproved" || 
               mr.backendStatus === "FinanceRejected" ||
               (mr.status as string) === "Waiting for Finance Approval" ||
               (mr.status as string) === "Revision Needed";
      });
      
      pendingMrs.sort((a, b) => {
        const aReady = a.isReadyForFinance ? 1 : 0;
        const bReady = b.isReadyForFinance ? 1 : 0;
        if (aReady !== bReady) return bReady - aReady;
        return 0;
      });
      
      setMrs(pendingMrs);
    } catch (error) {
      console.warn('Error processing purchase requests for finance approval.', error);
    }
  }, [purchaseRequests, supplierPayments]);

  const filteredPos = pos.filter(po => 
    po.id.toLowerCase().includes(search.toLowerCase()) || 
    po.supplier.toLowerCase().includes(search.toLowerCase())
  );

  const pendingPosList = filteredPos.filter(po => po.paymentStatus !== 'Paid');
  const historyPosList = filteredPos.filter(po => po.paymentStatus === 'Paid');
  const paginatedHistory = historyPosList.slice((historyPage - 1) * ITEMS_PER_PAGE, historyPage * ITEMS_PER_PAGE);

  const filteredMrs = mrs.filter(mr => 
    mr.id.toLowerCase().includes(search.toLowerCase()) || 
    mr.department.toLowerCase().includes(search.toLowerCase()) ||
    mr.requestor.toLowerCase().includes(search.toLowerCase())
  );

  const pendingPosCount = pos.filter(p => p.paymentStatus !== 'Paid').length;
  const pendingMrsCount = mrs.filter(m => m.backendStatus === 'SupervisorApproved').length;

  const handlePay = async () => {
    if (!selectedPo) return;
    try {
      await financeApi.submitSupplierPayment({
        poNumber: selectedPo.id,
        supplierName: selectedPo.supplier,
        paymentDate: new Date().toISOString().split('T')[0],
        amount: calcTotal(selectedPo.items),
        bankName: selectedPo.supplier,
        notes: notes,
        proofFile: proofFile ?? undefined
      });
      await refresh();
      setSelectedPo(null);
      setCategory('');
      setNotes('');
      setProofFile(null);
    } catch (error) {
      console.warn('Failed to process supplier payment.', error);
      setDialogMsg({ title: "Gagal Menyimpan", message: "Gagal menyimpan pembayaran. Cek koneksi API." });
    }
  };

  const handleReviewPr = async (decision: 'Accept' | 'Reject', reason?: string) => {
    if (!selectedMr || !currentUser) return;
    if (decision === 'Reject' && (!reason || !reason.trim())) {
      setDialogMsg({ title: "Peringatan", message: "Alasan penolakan anggaran wajib diisi agar tim Purchasing tahu apa yang harus direvisi!" });
      return;
    }
    setIsApproving(true);
    try {
      await purchasingApi.reviewPurchaseRequest(selectedMr.backendId, {
        reviewedByUserId: currentUser.id,
        decision,
        reviewStage: 'Finance',
        rejectionReason: decision === 'Reject' ? reason : undefined
      });
      setShowRejectModal(false);
      setRejectReasonInput("");
      await refresh();
      setSelectedMr(null);
    } catch (error) {
      console.warn('Failed to review PR.', error);
      setDialogMsg({ title: "Gagal Memproses", message: "Gagal memproses review PR. Cek koneksi API." });
    } finally {
      setIsApproving(false);
    }
  };

  return (
    <div className="p-4 lg:p-6 space-y-5 min-h-full">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
        <div>
          <h1 className="text-xl font-bold text-slate-900">Tagihan Supplier & Persetujuan Anggaran</h1>
          <p className="text-sm text-slate-500 mt-0.5">Persetujuan anggaran (PR) dan pembayaran Tagihan Supplier (AP).</p>
        </div>
        <div className="flex gap-2">
          {pendingMrsCount > 0 && (
            <div className="bg-[#C8102E] text-white border-transparent shadow-sm px-4 py-2 rounded-md flex items-center gap-2 text-sm font-semibold">
              <FileText size={16} />
              {pendingMrsCount} PR Menunggu
            </div>
          )}
          {pendingPosCount > 0 && (
            <div className="bg-amber-500 text-white border-transparent shadow-sm px-4 py-2 rounded-md flex items-center gap-2 text-sm font-semibold">
              <AlertCircle size={16} />
              {pendingPosCount} Tagihan AP Menunggu
            </div>
          )}
        </div>
      </div>

      <Tabs defaultValue="budget" className="w-full">
        <TabsList className="mb-4 bg-slate-100 rounded-md p-1">
          <TabsTrigger value="budget" className="flex items-center gap-2 rounded-sm">
            <FileText size={15} /> Persetujuan Anggaran PR
            {pendingMrsCount > 0 && <span className="bg-red-100 text-red-700 px-1.5 py-0.5 rounded-full text-xs ml-1">{pendingMrsCount}</span>}
          </TabsTrigger>
          <TabsTrigger value="payment" className="flex items-center gap-2 rounded-sm">
            <CheckSquare size={15} /> Tagihan Supplier (AP)
            {pendingPosCount > 0 && <span className="bg-amber-100 text-amber-700 px-1.5 py-0.5 rounded-full text-xs ml-1">{pendingPosCount}</span>}
          </TabsTrigger>
          <TabsTrigger value="history" className="flex items-center gap-2 rounded-sm" onClick={() => setHistoryPage(1)}>
            <CheckCircle2 size={15} /> Riwayat (AP)
          </TabsTrigger>
        </TabsList>

        <TabsContent value="budget">
          <PrBudgetTab 
            filteredMrs={filteredMrs} 
            search={search} 
            setSearch={setSearch} 
          />
        </TabsContent>

        <TabsContent value="payment">
          <ApPaymentTab 
            pendingPosList={pendingPosList} 
            search={search} 
            setSearch={setSearch} 
          />
        </TabsContent>

        <TabsContent value="history">
          <ApHistoryTab 
            historyPosList={historyPosList} 
            paginatedHistory={paginatedHistory} 
            search={search} 
            setSearch={setSearch} 
            historyPage={historyPage} 
            setHistoryPage={setHistoryPage} 
            ITEMS_PER_PAGE={ITEMS_PER_PAGE} 
          />
        </TabsContent>
      </Tabs>

      {/* PR Review Modal */}
      {selectedMr && (
        <PrReviewModal 
          selectedMr={selectedMr} 
          setSelectedMr={setSelectedMr} 
          isApproving={isApproving} 
          setShowRejectModal={setShowRejectModal} 
          handleReviewPr={handleReviewPr} 
        />
      )}

      {showRejectModal && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-lg w-full max-w-md p-6 shadow-xl border border-slate-100">
            <h3 className="text-lg font-bold text-slate-800 mb-2">Tolak Persetujuan Anggaran</h3>
            <p className="text-sm text-slate-600 mb-4">
              Silakan berikan alasan penolakan anggaran ini agar tim Purchasing tahu apa yang harus direvisi.
            </p>
            <textarea
              className="w-full rounded border border-slate-300 p-3 text-sm outline-none focus:border-red-500 min-h-[100px] mb-4"
              placeholder="Contoh: Harga estimasi melebihi batas standar HPS. Cari alternatif supplier."
              value={rejectReasonInput}
              onChange={(e) => setRejectReasonInput(e.target.value)}
            />
            <div className="flex justify-end gap-3">
              <button
                type="button"
                onClick={() => { setShowRejectModal(false); setRejectReasonInput(""); }}
                className="px-4 py-2 rounded text-sm font-semibold text-slate-600 bg-slate-100 hover:bg-slate-200 transition-colors"
                disabled={isApproving}
              >
                Batal
              </button>
              <button
                type="button"
                onClick={() => handleReviewPr('Reject', rejectReasonInput)}
                className="px-4 py-2 rounded text-sm font-semibold text-white bg-red-600 hover:bg-red-700 transition-colors disabled:opacity-50 flex items-center gap-2"
                disabled={isApproving || !rejectReasonInput.trim()}
              >
                {isApproving ? "Memproses..." : "Konfirmasi Tolak"}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Payment Modal */}
      {selectedPo && (
        <ApPaymentModal 
          selectedPo={selectedPo} 
          setSelectedPo={setSelectedPo} 
          suppliers={suppliers} 
          category={category} 
          setCategory={setCategory} 
          proofFile={proofFile} 
          setProofFile={setProofFile} 
          notes={notes} 
          setNotes={setNotes} 
          handlePay={handlePay} 
        />
      )}

      {dialogMsg && (
        <div className="fixed inset-0 bg-black/50 z-[60] flex items-center justify-center p-4 animate-in fade-in duration-150">
          <div className="bg-white rounded-lg w-full max-w-sm p-6 shadow-2xl border border-slate-100 text-center">
            <div className="w-12 h-12 rounded-full bg-amber-50 text-amber-600 flex items-center justify-center mx-auto mb-4 border border-amber-200">
              <AlertCircle size={24} />
            </div>
            <h3 className="text-lg font-bold text-slate-800 mb-2">{dialogMsg.title}</h3>
            <p className="text-sm text-slate-600 mb-6 leading-relaxed">{dialogMsg.message}</p>
            <button
              type="button"
              onClick={() => setDialogMsg(null)}
              className="w-full py-2.5 rounded-md text-sm font-semibold text-white bg-slate-900 hover:bg-slate-800 transition-colors shadow-sm"
            >
              Mengerti
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

import { useMemo, useState } from 'react';
import {
  AreaChart, Area, BarChart, Bar, PieChart, Pie, Cell,
  XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer
} from 'recharts';
import {
  Download, TrendingUp, FileText,
  BarChart3, PieChart as PieIcon, Pencil
} from 'lucide-react';
import {
  formatIDR, type Invoice
} from './mockData';
import { useFinanceData } from './useFinanceData';

const PIE_COLORS = ['#16a34a', '#d97706', '#dc2626', '#C8102E'];

const formatIDRShort = (v: number) => {
  if (v >= 1_000_000_000) return `Rp ${(v / 1_000_000_000).toFixed(1)}M`;
  if (v >= 1_000_000) return `Rp ${(v / 1_000_000).toFixed(0)}Jt`;
  return `Rp ${(v / 1_000).toFixed(0)}K`;
};

const CustomTooltip = ({ active, payload, label }: any) => {
  if (active && payload?.length) {
    return (
      <div className="bg-[#0D1B2A] border border-slate-700 rounded-lg px-4 py-3 shadow-xl text-xs text-white">
        <p className="font-semibold mb-2 text-slate-300">{label}</p>
        {payload.map((p: any) => (
          <div key={p.name} className="flex justify-between gap-4">
            <span style={{ color: p.color }}>{p.name}</span>
            <span className="font-medium">{typeof p.value === 'number' ? formatIDRShort(p.value) : p.value}</span>
          </div>
        ))}
      </div>
    );
  }
  return null;
};

const TABS = [
  { id: 'revenue', label: 'Pendapatan', icon: TrendingUp },
  { id: 'invoice', label: 'Invoice', icon: FileText },
  { id: 'customer', label: 'Pelanggan', icon: BarChart3 },
];

function buildMonthlyTableData(invoices: Invoice[]) {
  const monthNames = ['Januari', 'Februari', 'Maret', 'April', 'Mei', 'Juni', 'Juli', 'Agustus', 'September', 'Oktober', 'November', 'Desember'];
  const byMonth = new Map<string, { month: string; invoiced: number; collected: number; outstanding: number; invoiceCount: number }>();

  invoices.forEach(invoice => {
    const date = new Date(invoice.issueDate);
    const key = `${date.getFullYear()}-${date.getMonth()}`;
    const row = byMonth.get(key) ?? {
      month: `${monthNames[date.getMonth()] ?? invoice.issueDate.slice(5, 7)} ${date.getFullYear()}`,
      invoiced: 0,
      collected: 0,
      outstanding: 0,
      invoiceCount: 0,
    };

    row.invoiced += invoice.amount;
    row.collected += invoice.paidAmount;
    row.outstanding += Math.max(0, invoice.amount - invoice.paidAmount);
    row.invoiceCount += 1;
    byMonth.set(key, row);
  });

  return [...byMonth.entries()]
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([, row]) => row)
    .slice(-6);
}

function buildTopCustomersData(invoices: Invoice[]) {
  const byCustomer = new Map<string, number>();
  invoices.forEach(invoice => {
    byCustomer.set(invoice.customerName, (byCustomer.get(invoice.customerName) ?? 0) + invoice.paidAmount);
  });

  return [...byCustomer.entries()]
    .map(([name, revenue]) => ({
      name: name.replace(/^PT\.?\s+/i, '').replace(/^CV\.?\s+/i, '').replace(/^UD\.?\s+/i, ''),
      revenue,
    }))
    .sort((a, b) => b.revenue - a.revenue);
}

export function FinanceReports() {
  const [activeTab, setActiveTab] = useState('revenue');
  const [dateRange, setDateRange] = useState('6M');
  const [isEditingTarget, setIsEditingTarget] = useState(false);
  const { invoices, monthlyRevenueData, invoiceStatusData, monthlyTarget, updateMonthlyTarget } = useFinanceData();
  const [targetInput, setTargetInput] = useState(formatIDR(monthlyTarget));

  const monthlyTableData = useMemo(() => buildMonthlyTableData(invoices), [invoices]);
  const topCustomersData = useMemo(() => buildTopCustomersData(invoices), [invoices]);
  const totalInvoiced = monthlyTableData.reduce((s, m) => s + m.invoiced, 0);
  const totalCollected = monthlyTableData.reduce((s, m) => s + m.collected, 0);
  const collectionRate = totalInvoiced > 0 ? ((totalCollected / totalInvoiced) * 100).toFixed(1) : '0.0';

  return (
    <div className="p-4 lg:p-6 space-y-5 min-h-full">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
        <div>
          <h1 className="text-xl text-slate-900">Laporan Keuangan</h1>
          <p className="text-sm text-slate-500 mt-0.5">Analisis kinerja keuangan PT Pratama Jaya Tekindo</p>
        </div>
        <div className="flex items-center gap-2">
          <div className="flex items-center bg-slate-100 rounded-lg p-1">
            {['1M', '3M', '6M', '1Y'].map(r => (
              <button
                key={r}
                onClick={() => setDateRange(r)}
                className={`text-xs px-3 py-1.5 rounded-md font-medium transition-all ${
                  dateRange === r ? 'bg-white text-slate-800 shadow-sm' : 'text-slate-500 hover:text-slate-700'
                }`}
              >
                {r}
              </button>
            ))}
          </div>
          <button className="flex items-center gap-1.5 text-sm text-slate-600 border border-slate-200 bg-white rounded-lg px-3 py-1.5 hover:bg-slate-50 transition-colors shadow-sm">
            <Download size={14} />
            <span className="hidden sm:inline">Export Laporan</span>
          </button>
        </div>
      </div>

      {/* Summary KPI Row */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
        {[
          { label: 'Total Ditagihkan', value: formatIDRShort(totalInvoiced), sub: '6 bulan', icon: FileText, color: 'text-red-600', bg: 'bg-red-50' },
          { label: 'Total Terkumpul', value: formatIDRShort(totalCollected), sub: 'sudah diterima', icon: TrendingUp, color: 'text-green-600', bg: 'bg-green-50' },
          { label: 'Collection Rate', value: `${collectionRate}%`, sub: 'performa penagihan', icon: PieIcon, color: 'text-purple-600', bg: 'bg-purple-50' },
          { label: 'Rata-rata/Bulan', value: formatIDRShort(totalCollected / Math.max(1, monthlyTableData.length)), sub: '6 bulan terakhir', icon: BarChart3, color: 'text-amber-600', bg: 'bg-amber-50' },
        ].map(k => (
          <div key={k.label} className="bg-white border border-slate-200 rounded-xl px-4 py-4 shadow-sm">
            <div className="flex items-center justify-between mb-2">
              <p className="text-xs text-slate-400">{k.label}</p>
              <div className={`w-7 h-7 rounded-lg ${k.bg} flex items-center justify-center`}>
                <k.icon size={13} className={k.color} />
              </div>
            </div>
            <p className={`text-lg font-bold ${k.color}`}>{k.value}</p>
            <p className="text-xs text-slate-400 mt-0.5">{k.sub}</p>
          </div>
        ))}
      </div>

      {/* Tabs */}
      <div className="flex items-center gap-2 border-b border-slate-200">
        {TABS.map(tab => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id)}
            className={`flex items-center gap-2 px-4 py-2.5 text-sm font-medium transition-all border-b-2 -mb-px ${
              activeTab === tab.id
                ? 'text-red-600 border-red-600'
                : 'text-slate-500 border-transparent hover:text-slate-700'
            }`}
          >
            <tab.icon size={14} />
            {tab.label}
          </button>
        ))}
      </div>

      {/* Revenue Tab */}
      {activeTab === 'revenue' && (
        <div className="space-y-4">
          <div className="grid grid-cols-1 xl:grid-cols-2 gap-4">
            {/* Revenue vs Invoiced */}
            <div className="bg-white rounded-xl border border-slate-200 p-5 shadow-sm">
              <div className="mb-4">
                <h3 className="text-sm font-semibold text-slate-800">Pendapatan vs Ditagihkan</h3>
                <p className="text-xs text-slate-400 mt-0.5">Perbandingan bulanan</p>
              </div>
              <ResponsiveContainer width="100%" height={220}>
                <AreaChart data={monthlyRevenueData}>
                  <defs>
                    <linearGradient id="colGrad" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="5%" stopColor="#16a34a" stopOpacity={0.15} />
                      <stop offset="95%" stopColor="#16a34a" stopOpacity={0} />
                    </linearGradient>
                    <linearGradient id="invGrad2" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="5%" stopColor="#C8102E" stopOpacity={0.1} />
                      <stop offset="95%" stopColor="#C8102E" stopOpacity={0} />
                    </linearGradient>
                  </defs>
                  <CartesianGrid strokeDasharray="3 3" stroke="#f1f5f9" vertical={false} />
                  <XAxis dataKey="month" tick={{ fontSize: 11, fill: '#94a3b8' }} axisLine={false} tickLine={false} />
                  <YAxis tickFormatter={formatIDRShort} tick={{ fontSize: 10, fill: '#94a3b8' }} axisLine={false} tickLine={false} width={70} />
                  <Tooltip content={<CustomTooltip />} />
                  <Area type="monotone" dataKey="invoiced" name="Ditagihkan" stroke="#C8102E" strokeWidth={2} fill="url(#invGrad2)" dot={false} />
                  <Area type="monotone" dataKey="revenue" name="Terkumpul" stroke="#16a34a" strokeWidth={2.5} fill="url(#colGrad)" dot={{ r: 3, fill: '#16a34a' }} />
                </AreaChart>
              </ResponsiveContainer>
            </div>

            {/* Monthly Bar */}
            <div className="bg-white rounded-xl border border-slate-200 p-5 shadow-sm group">
              <div className="mb-4 flex items-start justify-between">
                <div>
                  <h3 className="text-sm font-semibold text-slate-800">Perbandingan Target vs Realisasi</h3>
                  {isEditingTarget ? (
                    <div className="flex items-center gap-2 mt-1">
                      <input
                        type="text"
                        value={targetInput}
                        onChange={(e) => {
                          const raw = e.target.value.replace(/\D/g, '');
                          setTargetInput(formatIDR(parseInt(raw || '0', 10)));
                        }}
                        className="text-xs font-semibold text-slate-900 border-b border-slate-300 focus:border-red-600 focus:outline-none bg-transparent p-0 m-0 w-32"
                        autoFocus
                        onBlur={() => {
                          const val = parseInt(targetInput.replace(/\D/g, ''), 10) || 0;
                          updateMonthlyTarget(val);
                          setIsEditingTarget(false);
                        }}
                        onKeyDown={(e) => {
                          if (e.key === 'Enter') {
                            const val = parseInt(targetInput.replace(/\D/g, ''), 10) || 0;
                            updateMonthlyTarget(val);
                            setIsEditingTarget(false);
                          }
                        }}
                      />
                    </div>
                  ) : (
                    <div className="flex items-center gap-2 mt-0.5">
                      <p className="text-xs text-slate-400">Target bulanan {formatIDRShort(monthlyTarget)}</p>
                      <button 
                        onClick={() => {
                          setTargetInput(formatIDR(monthlyTarget));
                          setIsEditingTarget(true);
                        }}
                        className="opacity-0 group-hover:opacity-100 transition-opacity text-slate-400 hover:text-red-600"
                      >
                        <Pencil size={12} />
                      </button>
                    </div>
                  )}
                </div>
              </div>
              <ResponsiveContainer width="100%" height={220}>
                <BarChart data={monthlyRevenueData} barGap={4}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#f1f5f9" vertical={false} />
                  <XAxis dataKey="month" tick={{ fontSize: 11, fill: '#94a3b8' }} axisLine={false} tickLine={false} />
                  <YAxis tickFormatter={formatIDRShort} tick={{ fontSize: 10, fill: '#94a3b8' }} axisLine={false} tickLine={false} width={70} />
                  <Tooltip content={<CustomTooltip />} />
                  <Bar dataKey="target" name="Target" fill="#e2e8f0" radius={[3, 3, 0, 0]} />
                  <Bar dataKey="revenue" name="Realisasi" fill="#C8102E" radius={[3, 3, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </div>

          {/* Monthly Summary Table */}
          <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
            <div className="px-5 py-4 border-b border-slate-100">
              <h3 className="text-sm font-semibold text-slate-800">Rekap Bulanan</h3>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead className="bg-slate-50 border-b border-slate-100">
                  <tr>
                    {['Bulan', 'Ditagihkan', 'Terkumpul', 'Outstanding', 'Jml Invoice', 'Collection Rate'].map(h => (
                      <th key={h} className="text-left px-5 py-3 text-xs font-semibold text-slate-500 uppercase tracking-wide whitespace-nowrap">
                        {h}
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-50">
                  {monthlyTableData.map((row, i) => {
                    const rate = ((row.collected / row.invoiced) * 100).toFixed(1);
                    const rateNum = parseFloat(rate);
                    return (
                      <tr key={i} className="hover:bg-slate-50/70 transition-colors">
                        <td className="px-5 py-3.5 font-medium text-slate-800">{row.month}</td>
                        <td className="px-5 py-3.5 text-slate-600">{formatIDR(row.invoiced)}</td>
                        <td className="px-5 py-3.5 font-semibold text-green-700">{formatIDR(row.collected)}</td>
                        <td className="px-5 py-3.5 text-amber-600">{formatIDR(row.outstanding)}</td>
                        <td className="px-5 py-3.5 text-slate-600">{row.invoiceCount} invoice</td>
                        <td className="px-5 py-3.5">
                          <div className="flex items-center gap-2">
                            <div className="flex-1 bg-slate-100 rounded-full h-1.5 w-16">
                              <div
                                className={`h-1.5 rounded-full ${rateNum >= 90 ? 'bg-green-500' : rateNum >= 70 ? 'bg-amber-500' : 'bg-red-500'}`}
                                style={{ width: `${Math.min(100, rateNum)}%` }}
                              />
                            </div>
                            <span className={`text-xs font-semibold ${rateNum >= 90 ? 'text-green-600' : rateNum >= 70 ? 'text-amber-600' : 'text-red-600'}`}>
                              {rate}%
                            </span>
                          </div>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
                <tfoot className="bg-slate-50 border-t border-slate-200">
                  <tr>
                    <td className="px-5 py-3 font-bold text-slate-800 text-xs uppercase">Total</td>
                    <td className="px-5 py-3 font-bold text-slate-800">{formatIDR(totalInvoiced)}</td>
                    <td className="px-5 py-3 font-bold text-green-700">{formatIDR(totalCollected)}</td>
                    <td className="px-5 py-3 font-bold text-amber-600">{formatIDR(totalInvoiced - totalCollected)}</td>
                    <td className="px-5 py-3 font-bold text-slate-700">{monthlyTableData.reduce((s, m) => s + m.invoiceCount, 0)}</td>
                    <td className="px-5 py-3 font-bold text-red-700">{collectionRate}%</td>
                  </tr>
                </tfoot>
              </table>
            </div>
          </div>
        </div>
      )}

      {/* Invoice Tab */}
      {activeTab === 'invoice' && (
        <div className="space-y-4">
          <div className="grid grid-cols-1 xl:grid-cols-2 gap-4">
            {/* Status Distribution */}
            <div className="bg-white rounded-xl border border-slate-200 p-5 shadow-sm">
              <h3 className="text-sm font-semibold text-slate-800 mb-4">Distribusi Status Invoice</h3>
              <div className="flex items-center gap-6">
                <ResponsiveContainer width={160} height={160}>
                  <PieChart>
                    <Pie data={invoiceStatusData} cx="50%" cy="50%" innerRadius={50} outerRadius={70} paddingAngle={4} dataKey="value">
                      {invoiceStatusData.map((entry, i) => <Cell key={`status-cell-${entry.name}`} fill={PIE_COLORS[i]} />)}
                    </Pie>
                    <Tooltip formatter={(v: any, n: any) => [v + ' invoice', n]} />
                  </PieChart>
                </ResponsiveContainer>
                <div className="flex-1 space-y-3">
                  {invoiceStatusData.map((d, i) => (
                    <div key={d.name} className="flex items-center justify-between">
                      <span className="flex items-center gap-2 text-sm text-slate-600">
                        <span className="w-3 h-3 rounded-sm inline-block" style={{ background: PIE_COLORS[i] }} />
                        {d.name}
                      </span>
                      <div className="text-right">
                        <span className="font-semibold text-slate-800">{d.value}</span>
                        <span className="text-xs text-slate-400 ml-1">({invoices.length > 0 ? ((d.value / invoices.length) * 100).toFixed(0) : '0'}%)</span>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            {/* Invoice by Amount */}
            <div className="bg-white rounded-xl border border-slate-200 p-5 shadow-sm">
              <h3 className="text-sm font-semibold text-slate-800 mb-4">Nilai Invoice per Status</h3>
              <ResponsiveContainer width="100%" height={180}>
                <BarChart data={[
                  { status: 'Lunas', value: invoices.filter(i => i.status === 'PAID').reduce((s, i) => s + i.amount, 0) },
                  { status: 'Menunggu', value: invoices.filter(i => i.status === 'PENDING').reduce((s, i) => s + i.amount, 0) },
                  { status: 'Jth Tempo', value: invoices.filter(i => i.status === 'OVERDUE').reduce((s, i) => s + i.amount, 0) },
                  { status: 'Sebagian', value: invoices.filter(i => i.status === 'PARTIAL').reduce((s, i) => s + i.amount, 0) },
                ]}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#f1f5f9" vertical={false} />
                  <XAxis dataKey="status" tick={{ fontSize: 11, fill: '#94a3b8' }} axisLine={false} tickLine={false} />
                  <YAxis tickFormatter={formatIDRShort} tick={{ fontSize: 10, fill: '#94a3b8' }} axisLine={false} tickLine={false} width={65} />
                  <Tooltip content={<CustomTooltip />} />
                  <Bar dataKey="value" name="Nilai" radius={[4, 4, 0, 0]}>
                    // eslint-disable-next-line unused-imports/no-unused-vars
                    {['#16a34a', '#d97706', '#dc2626', '#C8102E'].map((c, i) => (
                      <Cell key={`bar-cell-${c}`} fill={c} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </div>

          {/* Invoice Detail Table */}
          <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
            <div className="px-5 py-4 border-b border-slate-100">
              <h3 className="text-sm font-semibold text-slate-800">Daftar Invoice Aktif</h3>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead className="bg-slate-50 border-b border-slate-100">
                  <tr>
                    {['Invoice', 'Pelanggan', 'Total', 'Terbayar', 'Sisa', 'Status'].map(h => (
                      <th key={h} className="text-left px-5 py-3 text-xs font-semibold text-slate-500 uppercase tracking-wide">{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-50">
                  {invoices.map(inv => (
                    <tr key={inv.id} className="hover:bg-slate-50/50 transition-colors">
                      <td className="px-5 py-3 font-medium text-red-600 text-xs">{inv.invoiceNumber}</td>
                      <td className="px-5 py-3 text-slate-700">{inv.customerName}</td>
                      <td className="px-5 py-3 font-semibold text-slate-800">{formatIDR(inv.amount)}</td>
                      <td className="px-5 py-3 text-green-600">{formatIDR(inv.paidAmount)}</td>
                      <td className="px-5 py-3 text-amber-600">{formatIDR(inv.amount - inv.paidAmount)}</td>
                      <td className="px-5 py-3">
                        <span className={`text-[10px] font-semibold px-2 py-0.5 rounded-full ${
                          inv.status === 'PAID' ? 'bg-green-600 text-white border-transparent shadow-sm' :
                          inv.status === 'OVERDUE' ? 'bg-red-600 text-white border-transparent shadow-sm' :
                          inv.status === 'PARTIAL' ? 'bg-red-600 text-white border-transparent shadow-sm' :
                          'bg-amber-500 text-white border-transparent shadow-sm'
                        }`}>
                          {inv.status === 'PAID' ? 'Lunas' : inv.status === 'OVERDUE' ? 'Jth Tempo' : inv.status === 'PARTIAL' ? 'Sebagian' : 'Menunggu'}
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      )}

      {/* Customer Tab */}
      {activeTab === 'customer' && (
        <div className="space-y-4">
          <div className="grid grid-cols-1 xl:grid-cols-2 gap-4">
            {/* Top Customer Bar Chart */}
            <div className="bg-white rounded-xl border border-slate-200 p-5 shadow-sm xl:col-span-2">
              <h3 className="text-sm font-semibold text-slate-800 mb-4">Pendapatan per Pelanggan</h3>
              <ResponsiveContainer width="100%" height={240}>
                <BarChart data={topCustomersData} layout="vertical" margin={{ left: 10 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#f1f5f9" horizontal={false} />
                  <XAxis type="number" tickFormatter={formatIDRShort} tick={{ fontSize: 10, fill: '#94a3b8' }} axisLine={false} tickLine={false} />
                  <YAxis dataKey="name" type="category" tick={{ fontSize: 11, fill: '#64748b' }} axisLine={false} tickLine={false} width={100} />
                  <Tooltip content={<CustomTooltip />} />
                  <Bar dataKey="revenue" name="Pendapatan" fill="#C8102E" radius={[0, 4, 4, 0]} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </div>

          {/* Customer Table */}
          <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
            <div className="px-5 py-4 border-b border-slate-100">
              <h3 className="text-sm font-semibold text-slate-800">Detail Pelanggan</h3>
            </div>
            <table className="w-full text-sm">
              <thead className="bg-slate-50 border-b border-slate-100">
                <tr>
                  {['#', 'Pelanggan', 'Total Invoice', 'Total Pendapatan', 'Terakhir Transaksi', 'Status'].map(h => (
                    <th key={h} className="text-left px-5 py-3 text-xs font-semibold text-slate-500 uppercase tracking-wide">{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {topCustomersData
                  .sort((a, b) => b.revenue - a.revenue)
                  .map((c, i) => (
                    <tr key={c.name} className="hover:bg-slate-50/50 transition-colors">
                      <td className="px-5 py-3.5">
                        <span className={`w-6 h-6 rounded-full flex items-center justify-center text-xs font-bold ${
                          i === 0 ? 'bg-amber-500 text-white border-transparent shadow-sm' : i === 1 ? 'bg-slate-600 text-white border-transparent shadow-sm' : 'bg-orange-50 text-orange-600'
                        }`}>{i + 1}</span>
                      </td>
                      <td className="px-5 py-3.5 font-medium text-slate-800">{c.name}</td>
                      <td className="px-5 py-3.5 text-slate-600">{invoices.filter(inv => inv.customerName.includes(c.name.split(' ')[1] ?? c.name)).length} invoice</td>
                      <td className="px-5 py-3.5 font-semibold text-red-700">{formatIDR(c.revenue)}</td>
                      <td className="px-5 py-3.5 text-slate-500 text-xs">Nov 2024</td>
                      <td className="px-5 py-3.5">
                        <span className="text-[10px] font-semibold px-2 py-0.5 rounded-full bg-green-600 text-white border-transparent shadow-sm">Aktif</span>
                      </td>
                    </tr>
                  ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
}

import { useState, useMemo } from 'react';
import {
  Search, FileText, CreditCard, MinusCircle,
  PlusCircle, Download, LayoutList, Clock3,
  ArrowUpRight, ArrowDownLeft, RefreshCw
} from 'lucide-react';
import { formatIDR, formatDate, type TransactionType } from './mockData';
import { useFinanceData } from './useFinanceData';

const TYPE_CONFIG: Record<TransactionType, { label: string; icon: React.ComponentType<any>; color: string; bg: string }> = {
  INVOICE: { label: 'Invoice', icon: FileText, color: 'text-red-600', bg: 'bg-red-100' },
  PAYMENT: { label: 'Pembayaran', icon: CreditCard, color: 'text-green-600', bg: 'bg-green-100' },
  CREDIT_NOTE: { label: 'Kredit Nota', icon: MinusCircle, color: 'text-purple-600', bg: 'bg-purple-100' },
  DEBIT_NOTE: { label: 'Debit Nota', icon: PlusCircle, color: 'text-orange-600', bg: 'bg-orange-100' },
};

const STATUS_COLORS: Record<string, string> = {
  COMPLETED: '#16A34A',
  OUTSTANDING: '#F59E0B',
  PENDING_VERIFICATION: '#DC2626',
};
const STATUS_LABELS: Record<string, string> = {
  COMPLETED: 'Selesai',
  OUTSTANDING: 'Outstanding',
  PENDING_VERIFICATION: 'Verifikasi',
};

export function TransactionHistory() {
  const { transactions: financeTransactions } = useFinanceData();
  const [search, setSearch] = useState('');
  const [typeFilter, setTypeFilter] = useState<TransactionType | 'ALL'>('ALL');
  const [customerFilter, setCustomerFilter] = useState<string>('ALL');
  const [sortOrder, setSortOrder] = useState<'ASC' | 'DESC'>('DESC');
  const [viewMode, setViewMode] = useState<'table' | 'timeline'>('table');

  const transactionData = financeTransactions;

  const uniqueCustomers = useMemo(() => Array.from(new Set(transactionData.map(t => t.customerName))), [transactionData]);

  const filtered = useMemo(() => {
    const result = transactionData.filter(t => {
      const matchSearch = !search ||
        t.referenceNumber.toLowerCase().includes(search.toLowerCase()) ||
        t.description.toLowerCase().includes(search.toLowerCase()) ||
        t.customerName.toLowerCase().includes(search.toLowerCase());
      const matchType = typeFilter === 'ALL' || t.type === typeFilter;
      const matchCustomer = customerFilter === 'ALL' || t.customerName === customerFilter;
      return matchSearch && matchType && matchCustomer;
    });

    result.sort((a, b) => {
      const dateA = new Date(a.date).getTime();
      const dateB = new Date(b.date).getTime();
      return sortOrder === 'ASC' ? dateA - dateB : dateB - dateA;
    });

    return result;
  }, [search, typeFilter, customerFilter, sortOrder, transactionData]);

  const totalCredit = transactionData.reduce((s, t) => s + t.credit, 0);
  const totalDebit = transactionData.reduce((s, t) => s + t.debit, 0);
  const currentBalance = transactionData[transactionData.length - 1]?.balance ?? 0;

  return (
    <div className="p-4 lg:p-6 space-y-5 min-h-full">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
        <div>
          <h1 className="text-xl text-slate-900">Riwayat Transaksi</h1>
          <p className="text-sm text-slate-500 mt-0.5">Log lengkap semua aktivitas keuangan</p>
        </div>
        <div className="flex items-center gap-2">
          <button className="flex items-center gap-1.5 text-sm text-slate-600 border border-slate-200 bg-white rounded-lg px-3 py-1.5 hover:bg-slate-50 transition-colors shadow-md">
            <Download size={14} />
            <span className="hidden sm:inline">Export</span>
          </button>
        </div>
      </div>

      {/* Balance Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
        <div className="bg-green-600 rounded-xl p-5 text-white shadow-sm">
          <div className="flex items-center justify-between mb-3">
            <p className="text-xs text-green-100">Total Penerimaan</p>
            <ArrowDownLeft size={16} className="text-green-200" />
          </div>
          <p className="text-xl font-bold">{formatIDR(totalCredit)}</p>
          <p className="text-xs text-green-200 mt-1">{transactionData.filter(t => t.credit > 0).length} transaksi kredit</p>
        </div>
        <div className="bg-slate-700 rounded-xl p-5 text-white shadow-sm">
          <div className="flex items-center justify-between mb-3">
            <p className="text-xs text-slate-300">Total Tagihan</p>
            <ArrowUpRight size={16} className="text-slate-300" />
          </div>
          <p className="text-xl font-bold">{formatIDR(totalDebit)}</p>
          <p className="text-xs text-slate-400 mt-1">{transactionData.filter(t => t.debit > 0).length} transaksi debit</p>
        </div>
        <div className="bg-[#0D1B2A] rounded-xl p-5 text-white shadow-sm">
          <div className="flex items-center justify-between mb-3">
            <p className="text-xs text-slate-400">Saldo Piutang</p>
            <RefreshCw size={14} className="text-slate-400" />
          </div>
          <p className="text-xl font-bold">{formatIDR(currentBalance)}</p>
          <p className="text-xs text-slate-500 mt-1">per hari ini</p>
        </div>
      </div>

      {/* Controls */}
      <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
        <div className="flex flex-col sm:flex-row sm:items-center gap-3 px-5 py-4 border-b border-slate-100">
          <div className="relative flex-1">
            <Search size={15} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
            <input
              value={search}
              onChange={e => setSearch(e.target.value)}
              placeholder="Cari referensi, deskripsi, atau pelanggan..."
              className="w-full pl-9 pr-4 py-2 text-sm border border-slate-200 rounded-lg bg-slate-50 focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-red-400 transition-all"
            />
          </div>
          <div className="flex items-center gap-2 flex-shrink-0">
            {/* Customer Filter */}
            <select
              value={customerFilter}
              onChange={e => setCustomerFilter(e.target.value)}
              className="text-sm border border-slate-200 rounded-lg px-3 py-1.5 bg-white text-slate-700 focus:outline-none focus:border-red-500 font-medium cursor-pointer"
            >
              <option value="ALL">Semua Pelanggan</option>
              {uniqueCustomers.map(c => <option key={c} value={c}>{c}</option>)}
            </select>
            {/* Type Filter */}
            <div className="flex items-center gap-1 bg-slate-100 rounded-lg p-1">
              {(['ALL', 'PAYMENT', 'INVOICE', 'CREDIT_NOTE'] as const).map(t => (
                <button
                  key={t}
                  onClick={() => setTypeFilter(t)}
                  className={`text-xs px-2.5 py-1.5 rounded-md font-medium transition-all ${
                    typeFilter === t ? 'bg-white text-slate-800 shadow-sm' : 'text-slate-500 hover:text-slate-700'
                  }`}
                >
                  {t === 'ALL' ? 'Semua' : TYPE_CONFIG[t]?.label ?? t}
                </button>
              ))}
            </div>
            {/* View Mode Toggle */}
            <div className="flex items-center border border-slate-200 rounded-lg overflow-hidden">
              <button
                onClick={() => setViewMode('table')}
                className={`p-2 transition-colors ${viewMode === 'table' ? 'bg-slate-800 text-white' : 'bg-white text-slate-400 hover:text-slate-600'}`}
              >
                <LayoutList size={15} />
              </button>
              <button
                onClick={() => setViewMode('timeline')}
                className={`p-2 transition-colors ${viewMode === 'timeline' ? 'bg-slate-800 text-white' : 'bg-white text-slate-400 hover:text-slate-600'}`}
              >
                <Clock3 size={15} />
              </button>
            </div>
          </div>
        </div>

        {/* Table View */}
        {viewMode === 'table' && (
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead className="bg-slate-50 border-b border-slate-100">
                <tr>
                  {['Tanggal', 'Referensi', 'Deskripsi', 'Pelanggan', 'Debit', 'Kredit', 'Saldo', 'Status'].map(h => (
                    <th 
                      key={h} 
                      className={`text-left px-4 py-3 text-xs font-semibold text-slate-500 uppercase tracking-wide whitespace-nowrap ${h === 'Tanggal' ? 'cursor-pointer hover:bg-slate-100 transition-colors group' : ''}`}
                      onClick={() => h === 'Tanggal' && setSortOrder(prev => prev === 'ASC' ? 'DESC' : 'ASC')}
                    >
                      <div className="flex items-center gap-1">
                        {h}
                        {h === 'Tanggal' && (
                          <span className="text-[10px] text-slate-400 group-hover:text-red-500">
                            {sortOrder === 'ASC' ? 'Γû▓' : 'Γû╝'}
                          </span>
                        )}
                      </div>
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {filtered.length === 0 ? (
                  <tr><td colSpan={8} className="text-center py-12 text-slate-400 text-sm">Tidak ada transaksi ditemukan</td></tr>
                ) : filtered.map(trx => {
                  const cfg = TYPE_CONFIG[trx.type];
                  return (
                    <tr key={trx.id} className="hover:bg-red-50/20 transition-colors">
                      <td className="px-4 py-3.5 text-slate-500 text-xs whitespace-nowrap">{formatDate(trx.date)}</td>
                      <td className="px-4 py-3.5">
                        <div className="flex items-center gap-2">
                          <div className={`w-6 h-6 rounded-md flex items-center justify-center flex-shrink-0 ${cfg.bg}`}>
                            <cfg.icon size={12} className={cfg.color} />
                          </div>
                          <span className="font-mono text-xs text-slate-600">{trx.referenceNumber}</span>
                        </div>
                      </td>
                      <td className="px-4 py-3.5">
                        <p className="text-slate-700 max-w-[200px] truncate">{trx.description}</p>
                        <p className="text-xs text-slate-400">{trx.category}</p>
                      </td>
                      <td className="px-4 py-3.5 text-slate-600 text-xs max-w-[120px] truncate">{trx.customerName}</td>
                      <td className="px-4 py-3.5 text-right">
                        {trx.debit > 0 ? (
                          <span className="font-medium text-slate-700">{formatIDR(trx.debit)}</span>
                        ) : <span className="text-slate-300">ΓÇö</span>}
                      </td>
                      <td className="px-4 py-3.5 text-right">
                        {trx.credit > 0 ? (
                          <span className="font-semibold text-green-600">{formatIDR(trx.credit)}</span>
                        ) : <span className="text-slate-300">ΓÇö</span>}
                      </td>
                      <td className="px-4 py-3.5 text-right">
                        <span className="font-medium text-slate-800 text-xs">{formatIDR(trx.balance)}</span>
                      </td>
                      <td className="px-4 py-3.5">
                        <span 
                          className="text-[10px] font-bold px-2 py-1 rounded-md shadow-sm uppercase tracking-wide"
                          style={{ backgroundColor: STATUS_COLORS[trx.status] || '#64748B', color: '#FFFFFF', border: 'none' }}
                        >
                          {STATUS_LABELS[trx.status] ?? trx.status}
                        </span>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}

        {/* Timeline View */}
        {viewMode === 'timeline' && (
          <div className="p-5">
            {filtered.length === 0 ? (
              <p className="text-center py-10 text-slate-400 text-sm">Tidak ada transaksi</p>
            ) : (
              <div className="relative">
                <div className="absolute left-5 top-2 bottom-2 w-px bg-slate-200" />
                <div className="space-y-4">
                  // eslint-disable-next-line unused-imports/no-unused-vars
                  {filtered.map((trx, idx) => {
                    const cfg = TYPE_CONFIG[trx.type];
                    return (
                      <div key={trx.id} className="flex gap-4 relative">
                        {/* Node */}
                        <div className={`w-10 h-10 rounded-full border-2 border-white shadow-md flex items-center justify-center flex-shrink-0 z-10 ${cfg.bg}`}>
                          <cfg.icon size={15} className={cfg.color} />
                        </div>
                        {/* Content */}
                        <div className="flex-1 bg-slate-50 rounded-xl border border-slate-100 p-4 hover:bg-white transition-colors hover:shadow-sm">
                          <div className="flex items-start justify-between gap-3">
                            <div>
                              <div className="flex items-center gap-2 flex-wrap">
                                <span className="font-medium text-slate-800 text-sm">{trx.description}</span>
                                <span 
                                  className="text-[10px] font-bold px-2 py-1 rounded-md shadow-sm uppercase tracking-wide"
                                  style={{ backgroundColor: STATUS_COLORS[trx.status] || '#64748B', color: '#FFFFFF', border: 'none' }}
                                >
                                  {STATUS_LABELS[trx.status] ?? trx.status}
                                </span>
                              </div>
                              <p className="text-xs text-slate-400 mt-0.5">{trx.referenceNumber} ┬╖ {trx.customerName}</p>
                            </div>
                            <div className="text-right flex-shrink-0">
                              {trx.credit > 0 ? (
                                <p className="font-bold text-green-600">+{formatIDR(trx.credit)}</p>
                              ) : (
                                <p className="font-bold text-slate-700">{formatIDR(trx.debit)}</p>
                              )}
                              <p className="text-xs text-slate-400 mt-0.5">{formatDate(trx.date)}</p>
                            </div>
                          </div>
                          <div className="mt-2 flex items-center gap-2">
                            <span className={`text-[10px] font-medium px-2 py-0.5 rounded ${cfg.bg} ${cfg.color}`}>
                              {cfg.label}
                            </span>
                            <span className="text-[11px] text-slate-400">Saldo: {formatIDR(trx.balance)}</span>
                          </div>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            )}
          </div>
        )}

        {/* Footer */}
        <div className="flex items-center justify-between px-5 py-3.5 border-t border-slate-100 bg-slate-50/50">
          <p className="text-xs text-slate-400">{filtered.length} dari {transactionData.length} transaksi</p>
          <p className="text-xs text-slate-500">Update terakhir: hari ini, 14:30 WIB</p>
        </div>
      </div>
    </div>
  );
}

import { useCallback, useEffect, useMemo, useState } from 'react';
import { financeApi, InvoiceCandidateDto, InvoiceDto, PaymentVerificationRequestDto } from '../../services/financeApi';
import {
  type Invoice,
  type InvoiceStatus,
  type Payment,
  type Transaction,
} from './mockData';

function mapStatus(status: string, paidAmount: number, totalAmount: number, dueDate?: string): InvoiceStatus {
  const normalized = status.toLowerCase();
  if (normalized === 'paid' || paidAmount >= totalAmount) return 'PAID';
  
  if (dueDate) {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const due = new Date(dueDate);
    due.setHours(0, 0, 0, 0);
    if (due < today) return 'OVERDUE';
  }

  if (normalized === 'partiallypaid') return 'PARTIAL';
  if (normalized === 'overdue') return 'OVERDUE';
  return 'PENDING';
}

function mapInvoice(invoice: InvoiceDto): Invoice {
  return {
    id: invoice.id,
    invoiceNumber: invoice.invoiceNumber,
    soNumber: invoice.salesOrderNumber,
    customerId: invoice.customerId,
    customerName: invoice.customerName,
    amount: invoice.totalAmount,
    paidAmount: invoice.paidAmount,
    paymentDate: invoice.payments[0]?.paymentDate,
    dueDate: invoice.dueDate,
    issueDate: invoice.invoiceDate,
    status: mapStatus(invoice.status, invoice.paidAmount, invoice.totalAmount, invoice.dueDate),
    notes: invoice.paymentSchedules.map(schedule => `${schedule.label}: ${schedule.percentage}%`).join(', '),
    ppn: invoice.taxAmount,
    paymentSchedules: invoice.paymentSchedules,
    items: invoice.items.map(item => ({
      id: item.salesOrderItemId,
      description: item.description,
      quantity: item.qty,
      unit: 'Pcs',
      unitPrice: item.unitPrice,
      total: item.lineTotal,
    })),
  };
}

function buildMonthlyData(invoices: Invoice[], monthlyTarget: number) {
  const months = ['Jan', 'Feb', 'Mar', 'Apr', 'Mei', 'Jun', 'Jul', 'Agu', 'Sep', 'Okt', 'Nov', 'Des'];
  const byMonth = new Map<string, { month: string; revenue: number; invoiced: number; target: number }>();

  invoices.forEach(invoice => {
    const date = new Date(invoice.issueDate);
    const key = `${date.getFullYear()}-${date.getMonth()}`;
    const month = months[date.getMonth()] ?? invoice.issueDate.slice(5, 7);
    const current = byMonth.get(key) ?? { month, revenue: 0, invoiced: 0, target: monthlyTarget };
    current.invoiced += invoice.amount;
    current.revenue += invoice.paidAmount;
    byMonth.set(key, current);
  });

  return [...byMonth.values()].slice(-6);
}

function buildStatusData(invoices: Invoice[]) {
  const labels: Record<InvoiceStatus, string> = {
    PAID: 'Lunas',
    PENDING: 'Menunggu',
    OVERDUE: 'Jatuh Tempo',
    PARTIAL: 'Sebagian',
  };

  return (['PAID', 'PENDING', 'OVERDUE', 'PARTIAL'] as InvoiceStatus[])
    .map(status => ({
      name: labels[status],
      value: invoices.filter(invoice => invoice.status === status).length,
    }))
    .filter(item => item.value > 0);
}

function paymentKey(invoiceId: string, paymentDate: string, amount: number) {
  return `${invoiceId}:${paymentDate}:${amount}`;
}

function mapPaymentVerificationStatus(status: string): Payment['status'] {
  const normalized = status.toLowerCase();
  if (normalized === 'verified') return 'VERIFIED';
  if (normalized === 'rejected') return 'REJECTED';
  return 'PENDING';
}

function mapPaymentVerifications(requests: PaymentVerificationRequestDto[]): Payment[] {
  return requests.map(request => ({
    id: request.id,
    invoiceId: request.invoiceId,
    invoiceNumber: request.invoiceNumber,
    soNumber: request.salesOrderNumber,
    customerName: request.customerName,
    amount: request.amount,
    paymentDate: request.paymentDate,
    paymentMethod: 'Transfer',
    bankRef: request.bankReference || request.id.slice(0, 8).toUpperCase(),
    bankName: request.bankName || 'Bank Transfer',
    status: mapPaymentVerificationStatus(request.status),
    proofAvailable: !!request.proofFileName,
    proofFileName: request.proofFileName || undefined,
    proofFileUrl: request.proofFileUrl || undefined,
    submittedBy: request.submittedBy,
    submittedAt: request.submittedAtUtc,
    notes: request.notes || undefined,
    verifiedBy: request.verifiedBy || undefined,
    verifiedAt: request.verifiedAtUtc ? request.verifiedAtUtc.slice(0, 10) : undefined,
    rejectionReason: request.rejectionReason || undefined,
  }));
}

function mapPayments(invoices: InvoiceDto[], verificationRequests: PaymentVerificationRequestDto[]): Payment[] {
  const verifiedProofKeys = new Set(
    verificationRequests
      .filter(request => request.status.toLowerCase() === 'verified')
      .map(request => paymentKey(request.invoiceId, request.paymentDate, request.amount))
  );

  const recordedPayments: Payment[] = invoices.flatMap(invoice => invoice.payments
    .filter(payment => !verifiedProofKeys.has(paymentKey(invoice.id, payment.paymentDate, payment.amount)))
    .map(payment => ({
    id: payment.id,
    invoiceId: invoice.id,
    invoiceNumber: invoice.invoiceNumber,
    soNumber: invoice.salesOrderNumber,
    customerName: invoice.customerName,
    amount: payment.amount,
    paymentDate: payment.paymentDate,
    paymentMethod: 'Transfer',
    bankRef: payment.id.slice(0, 8).toUpperCase(),
    bankName: invoice.bankName || 'Bank Transfer',
    status: 'VERIFIED',
    proofAvailable: true,
    notes: payment.notes || undefined,
    verifiedBy: 'Backend',
    verifiedAt: payment.paymentDate,
  })));

  return [...mapPaymentVerifications(verificationRequests), ...recordedPayments];
}

function buildTransactionsFromInvoices(invoices: InvoiceDto[]): Transaction[] {
  const rows: Array<Omit<Transaction, 'balance'>> = [];

  invoices.filter(invoice => {
    return invoice.payments.length > 0 || invoice.paidAmount > 0 || invoice.status !== 'PENDING';
  }).forEach(invoice => {
    rows.push({
      id: invoice.id,
      type: 'INVOICE',
      referenceNumber: invoice.invoiceNumber,
      description: `Invoice ${invoice.salesOrderNumber}`,
      debit: invoice.totalAmount,
      credit: 0,
      date: invoice.invoiceDate,
      status: invoice.remainingAmount > 0 ? 'OUTSTANDING' : 'COMPLETED',
      customerName: invoice.customerName,
      category: 'Invoice',
    });

    invoice.payments.forEach(payment => {
      rows.push({
        id: payment.id,
        type: 'PAYMENT',
        referenceNumber: `${invoice.invoiceNumber}/PAY`,
        description: `Pembayaran ${invoice.invoiceNumber}`,
        debit: 0,
        credit: payment.amount,
        date: payment.paymentDate,
        status: 'COMPLETED',
        customerName: invoice.customerName,
        category: 'Payment',
      });
    });
  });

  let balance = 0;
  return rows
    .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime())
    .map(row => {
      balance += row.debit - row.credit;
      return { ...row, balance };
    });
}

export function useFinanceData(enabled = true, fetchSupplierPayments = true, fetchOpeningBalance = true) {
  const [backendInvoices, setBackendInvoices] = useState<Invoice[]>([]);
  const [backendPayments, setBackendPayments] = useState<Payment[]>([]);
  const [backendTransactions, setBackendTransactions] = useState<Transaction[]>([]);
  const [supplierPayments, setSupplierPayments] = useState<any[]>([]);
  const [openingBalance, setOpeningBalance] = useState<number>(250_000_000);
  const [invoiceCandidates, setInvoiceCandidates] = useState<InvoiceCandidateDto[]>([]);
  const [isUsingBackend, setIsUsingBackend] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [monthlyTarget, setMonthlyTarget] = useState<number>(1_000_000_000);

  const refresh = useCallback(async () => {
    setIsLoading(true);
    try {
      const [invoicesResult, candidatesResult, paymentVerificationsResult, supplierPaymentsResult, openingBalanceResult, monthlyTargetResult] = await Promise.allSettled([
        financeApi.listInvoices(),
        financeApi.listInvoiceCandidates(),
        financeApi.listPaymentVerifications(),
        fetchSupplierPayments ? financeApi.listSupplierPayments() : Promise.resolve([]),
        fetchOpeningBalance ? financeApi.getOpeningBalance() : Promise.resolve(250_000_000),
        financeApi.getMonthlyTarget()
      ]);

      const invoices = invoicesResult.status === 'fulfilled' ? invoicesResult.value : [];
      const candidates = candidatesResult.status === 'fulfilled' ? candidatesResult.value : [];
      const paymentVerifications = paymentVerificationsResult.status === 'fulfilled' ? paymentVerificationsResult.value : [];
      const supplierPaymentsList = supplierPaymentsResult.status === 'fulfilled' ? supplierPaymentsResult.value : [];
      const balance = openingBalanceResult.status === 'fulfilled' ? openingBalanceResult.value : 250_000_000;
      const target = monthlyTargetResult.status === 'fulfilled' ? monthlyTargetResult.value : 1_000_000_000;

      setBackendInvoices(invoices.map(mapInvoice));
      setBackendPayments(mapPayments(invoices, paymentVerifications));
      setBackendTransactions(buildTransactionsFromInvoices(invoices));
      setInvoiceCandidates(candidates);
      setSupplierPayments(supplierPaymentsList);
      setOpeningBalance(balance);
      setMonthlyTarget(target);
      setIsUsingBackend(true);
    } catch (error) {
      console.warn('Finance API unavailable; finance seed data was not loaded.', error);
      setBackendInvoices([]);
      setBackendPayments([]);
      setBackendTransactions([]);
      setInvoiceCandidates([]);
      setSupplierPayments([]);
      setIsUsingBackend(false);
    } finally {
      setIsLoading(false);
    }
  }, []);

  const updateOpeningBalance = async (newBalance: number) => {
    if (isUsingBackend) {
      await financeApi.updateOpeningBalance(newBalance);
      setOpeningBalance(newBalance);
    }
  };

  const updateMonthlyTarget = async (target: number) => {
    if (isUsingBackend) {
      await financeApi.updateMonthlyTarget(target);
      setMonthlyTarget(target);
    } else {
      setMonthlyTarget(target);
    }
  };

  useEffect(() => {
    if (enabled) {
      void refresh();
    } else {
      setIsLoading(false);
    }
  }, [enabled, refresh]);

  const invoices = backendInvoices;
  const payments = backendPayments;
  const transactions = backendTransactions;

  return useMemo(() => ({
    invoices,
    payments,
    transactions,
    invoiceCandidates,
    supplierPayments,
    openingBalance,
    updateOpeningBalance,
    monthlyTarget,
    updateMonthlyTarget,
    isLoading,
    isUsingBackend,
    refresh,
    monthlyRevenueData: buildMonthlyData(invoices, monthlyTarget),
    invoiceStatusData: buildStatusData(invoices),
  }), [invoices, payments, transactions, invoiceCandidates, supplierPayments, openingBalance, monthlyTarget, isLoading, isUsingBackend, refresh]);
}

import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router";
import { PlayCircle, AlertTriangle, FileWarning, Loader2 } from "lucide-react";
import { useApp } from "../../context/AppContext";
import { SalesOrder } from "../../data/mockData";
import { productionApi } from "../../../services/productionApi";
import { isGuid, toBackendUserId } from "../../../services/backendIds";
import { masterDataApi } from "../../../services/masterDataApi";
import { S, getBackendSalesOrderId } from "../ProductionHelpers";

interface StockIssue {
  itemName: string;
  required: number;
  available: number;
  bomQty: number;
  productQty: number;
  specs?: Array<{ spec: string; quantity: number }>;
}

export function StartProductionModal({ so, onClose, onReturnToSpv }: { so: SalesOrder; onClose: () => void; onReturnToSpv?: () => void }) {
  const { currentUser, refreshBackendData } = useApp();
  const isSupervisor = currentUser?.role === 'Engineering Supervisor' || currentUser?.role === 'Owner' || currentUser?.role === 'Admin';
  const navigate = useNavigate();
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [backendError, setBackendError] = useState<string | null>(null);
  const [stockIssues, setStockIssues] = useState<StockIssue[] | null>(null);
  const [checkingStock, setCheckingStock] = useState(true);

  useEffect(() => {
    let cancelled = false;
    async function checkStock() {
      try {
        if (so.status === "Paused") {
          setStockIssues([]);
          setCheckingStock(false);
          return;
        }

        const issues: StockIssue[] = [];
        
        // Use the SPV's custom BOMs for checking stock, not the master data BOM
        // Since we need to know the stock levels, we can fetch all inventory items.
        // In a real production app we'd fetch only the needed IDs, but listInventory works for now.
        const allInventory = await masterDataApi.listInventory();
        if (cancelled) return;

        // 1. Get the unified list of materials needed for this SO, excluding customer materials
        // We use getMaterialOptions because it correctly falls back to Master Data BOM if Custom BOM is empty.
        const { getMaterialOptions } = await import("../ProductionHelpers");
        const materials = getMaterialOptions(so, false);

        // 2. Aggregate required quantities by inventoryItemId
        const aggregatedCustomBoms = new Map<string, { quantity: number; isCustomerMaterial: boolean; name: string; specs: Array<{ spec: string, quantity: number }> }>();
        
        for (const cb of materials) {
          let invId = cb.inventoryItemId;
          if (!invId) {
            const match = allInventory.find(i => i.name.toLowerCase() === (cb.itemName || cb.name || "").toLowerCase());
            if (match) invId = match.id;
          }
          if (!invId) continue;
          
          const existing = aggregatedCustomBoms.get(invId);
          if (existing) {
            existing.quantity += (cb.quantity || 1);
            existing.specs.push({ spec: cb.specification || "", quantity: cb.quantity || 1 });
          } else {
            aggregatedCustomBoms.set(invId, {
              quantity: cb.quantity || 1,
              isCustomerMaterial: !!cb.isCustomerMaterial,
              name: cb.itemName || cb.name || "Unknown Material",
              specs: [{ spec: cb.specification || "", quantity: cb.quantity || 1 }]
            });
          }
        }

        // 3. Check against available stock
        for (const [invId, req] of aggregatedCustomBoms.entries()) {
          if (req.isCustomerMaterial || req.quantity <= 0) continue; // Skip customer materials

          const invItem = allInventory.find(i => i.id === invId);
          const available = invItem?.currentStock || 0;
          const requiredQty = req.quantity;

          if (available < requiredQty) {
            const existingIssue = issues.find(i => i.itemName === req.name);
            if (existingIssue) {
              existingIssue.required += requiredQty;
              existingIssue.specs = [...(existingIssue.specs || []), ...req.specs];
            } else {
              issues.push({
                itemName: req.name,
                required: requiredQty,
                available,
                bomQty: requiredQty,
                productQty: 1, // Already multiplied in getMaterialOptions
                specs: req.specs.length > 0 ? req.specs : undefined
              });
            }
          }
        }

        if (!cancelled) setStockIssues(issues);
      } catch (err) {
        console.warn("Failed to check stock for start production", err);
      } finally {
        if (!cancelled) setCheckingStock(false);
      }
    }
    void checkStock();
    return () => { cancelled = true; };
  }, [so.items, so.id, so.bomsPerItem, so.status]);

  const hasStockIssues = stockIssues && stockIssues.length > 0;
  const canStart = !isSubmitting && !checkingStock && !hasStockIssues;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isSubmitting) return;

    setBackendError(null);

    const currentUserGuid = isGuid(currentUser?.id) ? currentUser!.id : toBackendUserId(currentUser);
    const assignedWorkerGuid = isGuid(so.assignedTo) ? so.assignedTo : null;
    const workerUserId = currentUserGuid || assignedWorkerGuid || "";

    const salesOrderId = getBackendSalesOrderId(so);
    if (!isGuid(salesOrderId) || !workerUserId) {
      setBackendError("Gagal: SO ini belum sinkron dengan backend (ID tidak valid) atau user pekerja tidak valid.");
      return;
    }

    try {
      setIsSubmitting(true);
      if (so.status === 'Paused') {
        await productionApi.resumeProduction(salesOrderId, {
          workerUserId,
          workerName: currentUser?.name || so.assignedName || "Engineering",
        });
      } else {
        await productionApi.startProduction(salesOrderId, {
          workerUserId,
          workerName: currentUser?.name || so.assignedName || "Engineering",
        });

        try {
          const { getMaterialOptions } = await import("../ProductionHelpers");
          const materials = getMaterialOptions(so, false);
          const deductItems: { inventoryItemId: string, quantity: number }[] = [];
          const allInventory = await masterDataApi.listInventory();
          
          for (const cb of materials) {
             if (cb.isCustomerMaterial || !cb.quantity) continue;
             let invId = cb.inventoryItemId;
             if (!invId) {
               const match = allInventory.find(i => i.name.toLowerCase() === (cb.itemName || cb.name || "").toLowerCase());
               if (match) invId = match.id;
             }
             if (invId) {
               const existing = deductItems.find(x => x.inventoryItemId === invId);
               if (existing) {
                 existing.quantity += cb.quantity;
               } else {
                 deductItems.push({ inventoryItemId: invId, quantity: cb.quantity });
               }
             }
          }
          
          if (deductItems.length > 0) {
             await masterDataApi.deductCustomBomMaterials({ 
               items: deductItems,
               reason: `Pemakaian Produksi PO ${so.soNumber || so.id} - Sistem BOM`
             });
          }
        } catch (err) {
          console.warn("BOM deduction failed in frontend, but production started.", err);
        }
      }

      await refreshBackendData();
      onClose();
    } catch (error: any) {
      console.warn("Failed to start production in backend.", error);
      const backendMsg = error?.response?.data?.message || error?.message || "Gagal mulai produksi di backend. Cek koneksi API atau data operator.";
      setBackendError(backendMsg);
    } finally {
      setIsSubmitting(false);
    }
  };

  let isLate = false;
  let daysLate = 0;
  if (so.deadline) {
    const todayStr = new Date().toISOString().split("T")[0];
    const deadlineStr = so.deadline.split("T")[0];
    const tDate = new Date(todayStr);
    const dDate = new Date(deadlineStr);
    if (tDate > dDate) {
      isLate = true;
      daysLate = Math.round((tDate.getTime() - dDate.getTime()) / (1000 * 60 * 60 * 24));
    }
  }

  const isStockError = backendError && (backendError.toLowerCase().includes("stock") || backendError.toLowerCase().includes("material"));

  return (
    <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
      <div style={{ background: S.white, borderRadius: 12, width: "100%", maxWidth: 450, fontFamily: S.font, overflow: "hidden" }}>
        <div style={{ padding: "16px 24px", borderBottom: `1px solid ${S.border}`, display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          <div>
            <h2 style={{ color: S.slate, margin: 0, fontSize: "18px" }}>{so.status === 'Paused' ? 'Lanjutkan Produksi' : 'Mulai Produksi'}</h2>
            <p style={{ color: S.secondary, margin: "2px 0 0", fontSize: "12.5px" }}>{so.id}</p>
          </div>
          <button onClick={onClose} style={{ background: "none", border: "none", cursor: "pointer", color: S.secondary, fontSize: "20px" }}>&times;</button>
        </div>
        <form onSubmit={handleSubmit} style={{ padding: "20px 24px", display: "flex", flexDirection: "column", gap: 16 }}>
          {isLate && (
            <div style={{ padding: "10px 12px", background: "#FEF2F2", border: "1px solid #FECACA", borderRadius: 8, color: "#B91C1C", fontSize: "13px", display: "flex", alignItems: "flex-start", gap: 8 }}>
              <div style={{ marginTop: 2, flexShrink: 0 }}><AlertTriangle size={16} /></div>
              <div>
                <strong>Peringatan Keterlambatan</strong>
                <p style={{ margin: "2px 0 0", fontSize: "13px" }}>Produksi ini telah melewati deadline selama <strong>{daysLate} hari</strong>.</p>
              </div>
            </div>
          )}

          {backendError && (
            <div style={{ padding: "12px", background: "#FEF2F2", border: "1px solid #FECACA", borderRadius: 8, color: "#B91C1C", fontSize: "13px", display: "flex", flexDirection: "column", gap: 8 }}>
              <div style={{ display: "flex", gap: 8, alignItems: "flex-start" }}>
                <div style={{ marginTop: 2, flexShrink: 0 }}><AlertTriangle size={16} /></div>
                <div>
                  <strong>{isStockError ? "Stok Material Tidak Cukup" : "Gagal Memulai Produksi"}</strong>
                  <p style={{ margin: "4px 0 0", fontSize: "12.5px", lineHeight: "1.4" }}>{backendError}</p>
                </div>
              </div>

              {isStockError && (
                <div style={{ marginTop: 4, display: "flex", justifyContent: "flex-end" }}>
                  {isSupervisor ? (
                    <button
                      type="button"
                      onClick={() => navigate(`/erp/production/mr/${so.id}`, { state: { stockIssues: stockIssues || [] } })}
                      style={{ padding: "6px 14px", background: "#B91C1C", color: "white", border: "none", borderRadius: 6, fontSize: "12.5px", fontWeight: 600, cursor: "pointer", display: "flex", alignItems: "center", gap: 6 }}
                    >
                      <FileWarning size={14} /> Buat Material Request
                    </button>
                  ) : (
                    <button
                      type="button"
                      onClick={() => { onClose(); if (onReturnToSpv) onReturnToSpv(); }}
                      style={{ padding: "6px 14px", background: "#B91C1C", color: "white", border: "none", borderRadius: 6, fontSize: "12.5px", fontWeight: 600, cursor: "pointer", display: "flex", alignItems: "center", gap: 6 }}
                    >
                      <FileWarning size={14} /> Kembalikan ke SPV
